import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"WAF — enumerated source for the Azure Local | Well-Architected Review","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-azure-local-checklist.md","filePath":"frameworks/waf-azure-local-checklist.md"}'),d={name:"frameworks/waf-azure-local-checklist.md"};function i(s,t,n,c,l,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="waf-—-enumerated-source-for-the-azure-local-well-architected-review" tabindex="-1">WAF — enumerated source for the Azure Local | Well-Architected Review <a class="header-anchor" href="#waf-—-enumerated-source-for-the-azure-local-well-architected-review" aria-label="Permalink to &quot;WAF — enumerated source for the Azure Local | Well-Architected Review&quot;">​</a></h1><p><strong>Enumerated 2026-08-01. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>The audit&#39;s DQ12 records why this file exists: <em>&quot;Writing rules against a framework you have not enumerated is how <code>waf.storage.yaml</code> happened&quot;</em> — a rule file scoring a WAF pillar that does not exist. A future <code>waf.azurelocal.yaml</code> is written against this enumeration and nothing else, and every rule in it must cite an item number from the table below.</p><h2 id="what-this-assessment-is" tabindex="-1">What this assessment is <a class="header-anchor" href="#what-this-assessment-is" aria-label="Permalink to &quot;What this assessment is&quot;">​</a></h2><p>Microsoft&#39;s <strong>Azure Local | Well-Architected Review</strong> is one of Microsoft&#39;s per-workload specialised reviews (§14, item 3 of <code>pmo/audits/AZURE-SCOUT-AUDIT.md</code>) — the Well-Architected Framework applied to the specific technology scope of Azure Local (platform, 2311 and later) and Azure Local VMs (workload). It sits alongside the &quot;Core Well-Architected Review&quot; rather than replacing it.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Source page</td><td><a href="https://learn.microsoft.com/en-us/azure/well-architected/service-guides/azure-local" target="_blank" rel="noreferrer">Architecture best practices for Azure Local</a></td></tr><tr><td>Framework version</td><td>Azure Well-Architected Framework, current (<code>learn.microsoft.com/azure/well-architected/</code>) — five pillars: Reliability, Security, Cost Optimization, Operational Excellence, Performance Efficiency</td></tr><tr><td>Extraction date</td><td>2026-08-01</td></tr><tr><td>Verification method</td><td>Full page fetched via the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool and read start to end. Every checklist bullet under each pillar&#39;s <strong>&quot;Workload design checklist&quot;</strong> heading is transcribed below, in the order it appears on the page.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>The interactive Microsoft Assessments version of this review (<code>learn.microsoft.com/assessments/</code>) is not published as text.</strong> Like SMART (see <code>smart-question-set.md</code>), the assessment tool renders a client-side application shell; its question text and numbering aren&#39;t extractable from documentation. What <em>is</em> published, and what this file enumerates, is the article&#39;s own <strong>&quot;Workload design checklist&quot;</strong> under each pillar — Microsoft&#39;s own words describe this as the place to &quot;start your design strategy&quot; for the review. It is the closest thing to a citable, stable checklist that Microsoft publishes for this workload, and it is organised by the same five pillars the interactive tool scores.</p><p>The <code>WAF-AZLOCAL-*</code> identifiers below are <strong>Scout&#39;s</strong>, stable and citable, and they are not Microsoft item numbers.</p><p><strong>Shelf life.</strong> This service guide is actively maintained (Azure Local ships new baseline builds on a regular cadence). Re-verify before quoting, and re-date this page when you do.</p><h2 id="the-enumeration-—-33-items-across-5-pillars" tabindex="-1">The enumeration — 33 items across 5 pillars <a class="header-anchor" href="#the-enumeration-—-33-items-across-5-pillars" aria-label="Permalink to &quot;The enumeration — 33 items across 5 pillars&quot;">​</a></h2><h3 id="reliability-waf-azlocal-re-—-6-items" tabindex="-1">Reliability (WAF-AZLOCAL-RE) — 6 items <a class="header-anchor" href="#reliability-waf-azlocal-re-—-6-items" aria-label="Permalink to &quot;Reliability (WAF-AZLOCAL-RE) — 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scope</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AZLOCAL-RE-01</td><td>Define workload reliability targets (SLOs) for the platform and workload</td><td>Platform + workload</td><td>❌ Organisational — no ARM property records an intended SLO</td></tr><tr><td>WAF-AZLOCAL-RE-02</td><td>Consider how performance and operations affect reliability (rightsizing, disk type choice, firmware currency)</td><td>Platform</td><td>⚠️ Partial — <code>Hybrid/Clusters</code> reports cluster health and node count; firmware/driver currency isn&#39;t collected</td></tr><tr><td>WAF-AZLOCAL-RE-03</td><td>Provide fault tolerance to the instance and its infrastructure dependencies (storage resiliency, network topology)</td><td>Platform</td><td>✅ <code>Hybrid/Clusters</code> (storage resiliency, node count) · <code>Hybrid/LogicalNetworks</code> (network topology)</td></tr><tr><td>WAF-AZLOCAL-RE-04</td><td>Build redundancy to provide resiliency (multi-instance deployment across sites)</td><td>Workload</td><td>⚠️ Partial — Scout sees one cluster&#39;s inventory per collection scope; cross-instance redundancy isn&#39;t correlated</td></tr><tr><td>WAF-AZLOCAL-RE-05</td><td>Plan and test recoverability (RTO/RPO, Azure Site Recovery)</td><td>Workload</td><td>❌ Unanswerable — recovery testing cadence isn&#39;t an ARM-readable property</td></tr><tr><td>WAF-AZLOCAL-RE-06</td><td>Configure and regularly test workload backup and restore procedures</td><td>Workload</td><td>✅ <code>Management/RecoveryVault</code>, <code>Management/BackupInstances</code> — presence and coverage are readable; test cadence is not</td></tr></tbody></table><h3 id="security-waf-azlocal-se-—-9-items" tabindex="-1">Security (WAF-AZLOCAL-SE) — 9 items <a class="header-anchor" href="#security-waf-azlocal-se-—-9-items" aria-label="Permalink to &quot;Security (WAF-AZLOCAL-SE) — 9 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scope</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AZLOCAL-SE-01</td><td>Review the security baselines (drift protection, regulatory standards)</td><td>Platform</td><td>⚠️ Partial — <code>Security/DefenderSecureScore</code> reflects posture; the specific Azure Local security-baseline drift-control setting isn&#39;t a discrete collected property</td></tr><tr><td>WAF-AZLOCAL-SE-02</td><td>Detect, prevent, and respond to threats (Defender for Cloud, Defender for Servers)</td><td>Platform</td><td>✅ <code>Security/DefenderPricing</code>, <code>Security/DefenderAlerts</code>, <code>Security/DefenderAssessments</code></td></tr><tr><td>WAF-AZLOCAL-SE-03</td><td>Create segmentation to contain the blast radius (identity role separation, network isolation)</td><td>Platform + workload</td><td>⚠️ Partial — <code>Hybrid/LogicalNetworks</code> shows network segmentation; RBAC role-scope separation isn&#39;t collected (audit §14 item 2, gap B1)</td></tr><tr><td>WAF-AZLOCAL-SE-04</td><td>Use a trusted identity provider to control access (Microsoft Entra ID)</td><td>Platform + workload</td><td>✅ <code>Identity/*</code> collectors evidence Entra-backed identities; the specific Azure Local built-in-role assignment isn&#39;t yet a distinct collector</td></tr><tr><td>WAF-AZLOCAL-SE-05</td><td>Isolate, filter, and block network traffic (Network Controller, NSGs, virtual appliance chaining)</td><td>Platform + workload</td><td>✅ <code>Networking/PrivateEndpoint</code> and NSG collectors under <code>Networking/</code> for the workload side; Network Controller-specific policy objects aren&#39;t collected</td></tr><tr><td>WAF-AZLOCAL-SE-06</td><td>Encrypt data to protect against tampering (BitLocker at rest, trusted launch for Gen 2 VMs)</td><td>Platform + workload</td><td>❌ Unanswerable — BitLocker volume-encryption state and trusted-launch VM security-type flags aren&#39;t in the current <code>Hybrid/Clusters</code> / <code>Hybrid/VirtualMachines</code> field set</td></tr><tr><td>WAF-AZLOCAL-SE-07</td><td>Operationalise secret management (deployment-identity credential rotation)</td><td>Platform</td><td>❌ Unanswerable — rotation cadence isn&#39;t an ARM-readable property</td></tr><tr><td>WAF-AZLOCAL-SE-08</td><td>Enforce security controls via Azure Policy (application control, encrypted volumes)</td><td>Platform</td><td>✅ <code>Management/PolicyComplianceStates</code> against the relevant Azure Local built-in policy set</td></tr><tr><td>WAF-AZLOCAL-SE-09</td><td>Improve workload security posture with built-in policies (guest configuration, patch currency)</td><td>Workload</td><td>✅ <code>Management/PolicyComplianceStates</code> (Update Manager compliance path)</td></tr></tbody></table><h3 id="cost-optimization-waf-azlocal-co-—-6-items" tabindex="-1">Cost Optimization (WAF-AZLOCAL-CO) — 6 items <a class="header-anchor" href="#cost-optimization-waf-azlocal-co-—-6-items" aria-label="Permalink to &quot;Cost Optimization (WAF-AZLOCAL-CO) — 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scope</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AZLOCAL-CO-01</td><td>Estimate realistic costs as part of cost modeling</td><td>Platform + workload</td><td>❌ Organisational — a pricing-calculator exercise, not a collected property</td></tr><tr><td>WAF-AZLOCAL-CO-02</td><td>Optimize the cost of Azure Local hardware (validated OEM catalog choice)</td><td>Platform</td><td>❌ Unanswerable — hardware procurement choice predates any ARM resource</td></tr><tr><td>WAF-AZLOCAL-CO-03</td><td>Optimize licensing costs (Azure Hybrid Benefit)</td><td>Platform</td><td>⚠️ Partial — <code>Hybrid/VirtualMachines</code> records licence type where the API exposes it; Hybrid Benefit attach state for the cluster itself is not collected</td></tr><tr><td>WAF-AZLOCAL-CO-04</td><td>Save on environment costs (Hybrid Benefit, promotional/trial offers)</td><td>Platform</td><td>⚠️ Partial — same as CO-03</td></tr><tr><td>WAF-AZLOCAL-CO-05</td><td>Save on operational costs (Update Manager, right-sized observability retention)</td><td>Platform</td><td>⚠️ Partial — <code>Monitor/Workspaces</code> reports retention settings; Update Manager cost itself isn&#39;t a billable collected metric</td></tr><tr><td>WAF-AZLOCAL-CO-06</td><td>Evaluate density over isolation (AKS on Azure Local for containerised workloads)</td><td>Workload</td><td>✅ <code>Hybrid/ArcKubernetes</code> — presence indicates the density option is in use</td></tr></tbody></table><h3 id="operational-excellence-waf-azlocal-oe-—-6-items" tabindex="-1">Operational Excellence (WAF-AZLOCAL-OE) — 6 items <a class="header-anchor" href="#operational-excellence-waf-azlocal-oe-—-6-items" aria-label="Permalink to &quot;Operational Excellence (WAF-AZLOCAL-OE) — 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scope</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AZLOCAL-OE-01</td><td>Increase supportability (telemetry and diagnostics extension enabled by default)</td><td>Platform</td><td>✅ <code>Hybrid/ArcExtensions</code> — presence of the <code>AzureEdgeTelemetryAndDiagnostics</code> extension is readable</td></tr><tr><td>WAF-AZLOCAL-OE-02</td><td>Use Azure services to reduce operational complexity (Update Manager, Azure Monitor, Arc, Policy, Defender)</td><td>Platform</td><td>✅ Composite — <code>Management/PolicyComplianceStates</code>, <code>Security/DefenderPricing</code>, <code>Monitor/*</code>, <code>Hybrid/ArcExtensions</code> together evidence this</td></tr><tr><td>WAF-AZLOCAL-OE-03</td><td>Plan IP address network range requirements for workloads in advance</td><td>Workload</td><td>✅ <code>Hybrid/LogicalNetworks</code></td></tr><tr><td>WAF-AZLOCAL-OE-04</td><td>Enable monitoring and alerting for workloads deployed on Azure Local</td><td>Workload</td><td>✅ <code>Monitor/DataCollectionRules</code>, <code>Monitor/MetricAlertRules</code>, <code>Monitor/ActionGroups</code></td></tr><tr><td>WAF-AZLOCAL-OE-05</td><td>Use proper validation techniques for a safe deployment (environment checker tool)</td><td>Platform</td><td>❌ Unanswerable — a pre-deployment tool run, not a post-deployment ARM property</td></tr><tr><td>WAF-AZLOCAL-OE-06</td><td>Get current and stay current (solution catalog, Update Manager, automatic extension upgrade)</td><td>Platform</td><td>✅ <code>Hybrid/Clusters</code> reports the current build/version; <code>Hybrid/ArcExtensions</code> reports auto-upgrade setting per extension</td></tr></tbody></table><h3 id="performance-efficiency-waf-azlocal-pe-—-6-items" tabindex="-1">Performance Efficiency (WAF-AZLOCAL-PE) — 6 items <a class="header-anchor" href="#performance-efficiency-waf-azlocal-pe-—-6-items" aria-label="Permalink to &quot;Performance Efficiency (WAF-AZLOCAL-PE) — 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scope</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AZLOCAL-PE-01</td><td>Use Azure Local-validated hardware or premium solution builder offerings</td><td>Platform</td><td>❌ Unanswerable — hardware validation status isn&#39;t an ARM-readable property</td></tr><tr><td>WAF-AZLOCAL-PE-02</td><td>Choose the right physical disk types for the machines (all-flash vs. hybrid storage)</td><td>Platform</td><td>⚠️ Partial — <code>Hybrid/Clusters</code> may expose storage tier data depending on API version; not confirmed as a stable field</td></tr><tr><td>WAF-AZLOCAL-PE-03</td><td>Use the Azure Local sizer tool during the instance design phase</td><td>Platform</td><td>❌ Unanswerable — a pre-deployment sizing exercise</td></tr><tr><td>WAF-AZLOCAL-PE-04</td><td>Use all-flash storage for high-performance or low-latency workloads</td><td>Platform</td><td>⚠️ Partial — same field as PE-02</td></tr><tr><td>WAF-AZLOCAL-PE-05</td><td>Establish a performance baseline for instance storage before production</td><td>Platform</td><td>❌ Unanswerable — a benchmarking exercise (DiskSpd/VMFleet), not a collected property</td></tr><tr><td>WAF-AZLOCAL-PE-06</td><td>Consider ReFS deduplication and compression monitoring</td><td>Platform</td><td>❌ Unanswerable — not exposed via ARM/ARG for Azure Local storage</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pillar</th><th>Items</th><th>Answerable (✅)</th><th>Partial (⚠️)</th><th>Unanswerable (❌)</th></tr></thead><tbody><tr><td>Reliability</td><td>6</td><td>2</td><td>2</td><td>2</td></tr><tr><td>Security</td><td>9</td><td>4</td><td>2</td><td>3</td></tr><tr><td>Cost Optimization</td><td>6</td><td>1</td><td>3</td><td>2</td></tr><tr><td>Operational Excellence</td><td>6</td><td>5</td><td>0</td><td>1</td></tr><tr><td>Performance Efficiency</td><td>6</td><td>0</td><td>2</td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>33</strong></td><td><strong>12</strong></td><td><strong>9</strong></td><td><strong>12</strong></td></tr></tbody></table><p>12 of 33 items (36%) map cleanly to an existing collector. A further 9 are partially answerable — the collector exists but doesn&#39;t expose the specific field the checklist item asks about, which is build work rather than a new collector. 12 are genuinely unanswerable from ARM/ARG data (pre-deployment sizing/validation exercises, benchmarking runs, and organisational commitments), and any future <code>waf.azurelocal.yaml</code> must mark those <code>manual: true</code> rather than silently score them.</p><h2 id="what-this-means-for-the-rule-file" tabindex="-1">What this means for the rule file <a class="header-anchor" href="#what-this-means-for-the-rule-file" aria-label="Permalink to &quot;What this means for the rule file&quot;">​</a></h2><p>A future <code>waf.azurelocal.yaml</code> should cite <code>WAF-AZLOCAL-*</code> item numbers directly in each rule&#39;s <code>title</code> or a comment, the way <code>smart.migration.yaml</code> cites <code>SMART-*</code>. Items marked ❌ above are candidates for <code>manual: true</code> rules so they surface as questions for the customer rather than disappearing; items marked ⚠️ are the priority list for new collector fields, not new collectors.</p>',27)])])}const f=e(d,[["render",i]]);export{m as __pageData,f as default};
